package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.integration.githubwork.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_INTEGRATION_KAFKA_BOOTSTRAP",matches=".+")
class GitHubWorkKafkaIntegrationTest extends GitHubWorkFixtures {
 @Test void bothImmutableObservationStreamsReachKafkaWithExactOutboxBytesAndHeaders()throws Exception{sync("ISSUE",f.key(),0,batch("ISSUE",item(1,"ISSUE","OPEN","Issue","2020-01-02T00:00:00Z")));sync("PULL_REQUEST",f.key(),0,batch("PULL_REQUEST",item(2,"PULL_REQUEST","OPEN","PR","2020-01-02T00:00:00Z")));sync("ISSUE",f.key(),1,batch("ISSUE",item(1,"ISSUE","CLOSED","Closed","2020-01-03T00:00:00Z")));var expected=new HashMap<String,byte[]>();f.sql.query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (SELECT item_id FROM github_work_item WHERE space_id=?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),f.space).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(3,expected.size());
var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_INTEGRATION_KAFKA_BOOTSTRAP"));p.put("group.id","integration-validation-"+f.ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/integration-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/integration-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/integration-kafka-test/user.key")));try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("integration.github-issue.v1","integration.github-pull-request.v1"));var found=new HashSet<String>();long deadline=System.nanoTime()+Duration.ofSeconds(90).toNanos();while(found.size()<expected.size()&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){var e=GitHubWorkEventEnvelopeV1.parseFrom(row.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals(e.getAggregateId(),row.key());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.actor.toString(),e.getActorId());var payload=GitHubWorkItemObservedV1.parseFrom(e.getPayload());assertEquals("PRIVATE",payload.getVisibility());assertEquals("PUBLIC",payload.getSourceVisibility());String artifact=payload.getKind().equals("ISSUE")?"github-issue-events":"github-pull-request-events";for(var entry:Map.of("id",e.getEventId(),"trace_id",f.trace,"schema_group","integration","schema_artifact",artifact,"schema_version","1").entrySet())assertEquals(entry.getValue(),new String(row.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));found.add(e.getEventId());}assertEquals(expected.keySet(),found);}}}
